import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import Home3DView from '../../apps/room3d/Home3DView';
import {testCharacter} from './room3d-test-character';
import {createStarterHome} from '../../apps/room3d/starterHome.js';
const catalog=await fetch('/room3d/catalog.json').then(r=>r.json());
const initial=createStarterHome(catalog,'sage');initial.activeRoomId=initial.rooms[new URLSearchParams(location.search).has('furnished')?0:5].id;
const character={id:'qa-owner',name:'Sully',chibiStudio:{home3D:{state:testCharacter.state,hair:{bodyShape:'blank'}}}} as any;
const residents=[{id:'user',label:'你',state:testCharacter.state}];
function App(){const [home,setHome]=useState(initial),[editor,setEditor]=useState<any>(),[report,setReport]=useState('');
 const inspect=()=>{const s=editor.inspect();setReport(JSON.stringify({cameraPosition:s.cameraPosition,cameraTarget:s.cameraTarget,characterPosition:s.chibiPosition,heading:s.chibiRotation,anchor:editor.getResidentAnchor("qa-owner"),posture:s.chibiPosture,actor:s.furnitureActor,characterPosture:editor.getResidentPosture('qa-owner'),conversation:s.conversation,companion:editor.getCompanionSnapshot(),present:editor.getHomeScene().present,social:s.social,camera:s.cameraGestures,view:s.viewMode,records:editor.getState().records}));};
 return <><Home3DView value={home} character={character} residents={residents} onEditor={setEditor} onChange={setHome} onBack={()=>{}}/>{editor&&<details style={{position:'absolute',bottom:90,left:8,right:8,zIndex:100,background:'#fffdf4',fontSize:11,maxHeight:220,overflow:'auto'}}><summary>验收工具</summary><button onClick={()=>void editor.playSocial('home-hug','user','qa-owner').then(()=>{editor.advanceTime(3500);inspect();}).catch((e:Error)=>setReport(e.message))}>测试拥抱</button><button onClick={()=>{editor.advanceTime(20000);inspect();}}>看动作结束</button><button onClick={()=>{editor.summonOwner();inspect();}}>召唤房主</button><button onClick={()=>{editor.showHomeBubble('qa-owner','在这里坐一会儿吧。你刚才说的事，我还想听你多说一点。');inspect();}}>测试说话气泡</button><button onClick={()=>{const ok=editor.performCompanionAction('approach',1);setReport(JSON.stringify({started:ok,snapshot:editor.getCompanionSnapshot()}));}}>测试自主靠近</button><button onClick={()=>{const ok=editor.performCompanionAction('sit',1);setReport(JSON.stringify({started:ok,snapshot:editor.getCompanionSnapshot()}));}}>测试附近坐下</button><button onClick={()=>{editor.performCompanionAction('react',1);inspect();}}>测试互动回应</button><button onClick={()=>{editor.controlResident('user');editor.openPanel('chibi');setReport('打开用户动作，选择坐位');}}>用户家具动作</button><button onClick={()=>{editor.controlResident('qa-owner');editor.openPanel('chibi');setReport('角色动作');}}>角色家具动作</button><button onClick={()=>{editor.controlResident('user');inspect();}}>交回用户</button><button onClick={()=>{editor.beginHomeConversation()(8);inspect();}}>测试坐姿交谈</button><button onClick={()=>{editor.advanceTime(1000);inspect();}}>前进一秒</button><button onClick={()=>{editor.performCompanionAction('idle',.5);inspect();}}>测试空闲环顾</button><button onClick={()=>{editor.performCompanionAction('wander',.5);inspect();}}>测试自由走动</button><button onClick={()=>{const ok=editor.performCompanionAction('phone',.5);setReport(JSON.stringify({started:ok,snapshot:editor.getCompanionSnapshot()}));}}>测试看手机</button><button onClick={()=>{const ok=editor.performCompanionAction('furniture',.5);setReport(JSON.stringify({started:ok,snapshot:editor.getCompanionSnapshot()}));}}>测试家具活动</button><button onClick={async()=>{await editor.previewWave();editor.advanceTime(1500);inspect();}}>测试入场镜头</button><button onClick={inspect}>检查状态</button><output style={{display:'block',overflowWrap:'anywhere'}}>{report}</output></details>}</>;
}
const root=createRoot(document.getElementById('root')!);root.render(<App/>);import.meta.hot?.dispose(()=>root.unmount());
